-- WAREMAP | Ejecutar una sola vez en Supabase SQL Editor
create table if not exists public.ubicaciones (
  codigo text primary key,
  rack text not null,
  zona text not null,
  nivel integer not null check (nivel between 1 and 3),
  posicion integer not null check (posicion between 1 and 7),
  tipo3d text not null default 'vacio' check (tipo3d in ('vacio','big_bag','rollos_etiquetas','rollos_sachet')),
  productos jsonb not null default '[]'::jsonb check (jsonb_typeof(productos) = 'array'),
  actualizado_en timestamptz not null default now()
);
create or replace function public.marcar_actualizacion_waremap() returns trigger language plpgsql as $$
begin new.actualizado_en = now(); return new; end; $$;
drop trigger if exists trg_waremap_fecha on public.ubicaciones;
create trigger trg_waremap_fecha before update on public.ubicaciones for each row execute function public.marcar_actualizacion_waremap();
alter table public.ubicaciones enable row level security;
revoke all on public.ubicaciones from anon, authenticated;
grant usage on schema public to anon;
grant select on public.ubicaciones to anon;
drop policy if exists "Lectura pública WAREMAP" on public.ubicaciones;
create policy "Lectura pública WAREMAP" on public.ubicaciones for select to anon using (true);

